import {spanishLabel} from './branding.mjs';
import {vehicleForPerson,participantRole} from './transport.mjs';
import {journeysForPerson} from './document-model.mjs';
export function participantProgress(trip,person){
 const journeys=journeysForPerson(trip,person.id),vehicle=vehicleForPerson(trip,person,'Anada');
 const checks=[
  {key:'journeys',label:"Trayectos",done:person.ticket==='No cal'||(journeys.length>0&&journeys.every(s=>s.origin&&s.destination&&s.departure&&s.arrival&&!s.pending&&!s.stale)),detail:journeys.length?`${journeys.length} trayectos${journeys.some(s=>s.pending||s.stale)?' · revisar':''}`:person.ticket==='No cal'?'No cal':"Sin trayectos",action:journeys.length?'person-documents':'edit-person'},
  {key:'ticket',label:"Billete",done:['Comprat','No cal'].includes(person.ticket),detail:person.ticket==='Comprat'?'OK · Comprado':person.ticket||'Pendent',action:'edit-person'},
  {key:'checkin',label:'Check-in',done:['Fet','No cal'].includes(person.checkin),detail:person.checkin||'Pendent',action:'person-checkin'},
  {key:'pickup',label:"Recogida",done:!!person.pickup||!!(vehicle?.driver&&vehicle?.origin&&vehicle?.departure),detail:person.pickup|| (vehicle?`${vehicle.name}${vehicle.driver&&vehicle.origin&&vehicle.departure?'':' · incomplet'}`:"Sin asignar"),action:'edit-person'}
 ];
 return {person,checks,pending:checks.filter(c=>!c.done),complete:checks.every(c=>c.done)};
}
export function renderDashboard(trip,filter,esc){
 const rows=trip.people.map(p=>participantProgress(trip,p)),ready=rows.filter(r=>r.complete).length,total=rows.length,ratio=total?Math.round(100*ready/total):0;
 const shown=rows.filter(r=>filter==='all'||(filter==='pending'?r.pending.length:r.pending.some(c=>c.key===filter)));
 const filters=[['all',"Todos"],['pending',"Con pendientes"],['journeys',"Trayectos"],['ticket',"Billete"],['checkin','Check-in'],['pickup',"Recogida"]];
 return `<section class="trip-dashboard"><div class="readiness-banner"><div><span class="eyebrow">CONTROL DEL VIAJE</span><h2>${ready} de ${total} participantes preparados</h2><p>${total-ready} con gestiones pendientes · ${rows.reduce((n,r)=>n+r.pending.length,0)} comprobaciones por completar</p></div><div class="readiness-meter"><strong>${ratio}%</strong><progress value="${ready}" max="${total||1}" aria-label="Participantes con todas las comprobaciones completas"></progress></div></div><div class="dashboard-filters" role="group" aria-label="Filtrar participantes">${filters.map(([key,label])=>`<button class="button secondary ${filter===key?'selected-filter':''}" data-action="dashboard-filter" data-id="${key}" aria-pressed="${filter===key}">${label}${key==='all'?'':` · ${rows.filter(r=>key==='pending'?r.pending.length:r.pending.some(c=>c.key===key)).length}`}</button>`).join('')}</div>${shown.length?`<div class="table-wrap"><table class="readiness-table"><thead><tr><th>PARTICIPANTE</th><th>TRAYECTOS</th><th>BILLETE</th><th>CHECK-IN</th><th>RECOGIDA</th></tr></thead><tbody>${shown.map(r=>`<tr><td><button class="text-button" data-action="edit-person" data-id="${esc(r.person.id)}">${esc(r.person.name)}</button><small>${esc(spanishLabel(participantRole(r.person.role)))} · ${esc(spanishLabel(r.person.travelMode||'Avió'))}</small><small>${r.complete?'✓ A punt':`${r.pending.length} pendientes`}</small></td>${r.checks.map(c=>`<td><button class="readiness-cell ${c.done?'complete':'incomplete'}" data-action="${c.action}" data-id="${esc(r.person.id)}" aria-label="${esc(r.person.name+' · '+c.label+' · '+c.detail)}"><b aria-hidden="true">${c.done?'✓':'!'}</b><span>${esc(spanishLabel(c.detail))}</span></button></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>${total?"Ningún participante con esta gestión pendiente":"Encara no hi ha participantes"}</h3><p>${total?"Cambia el filtro para ver el resto del equipo.":"Vincula la carpeta y lee los documentos para empezar."}</p></div>`}<p class="small muted">Pulsa una casilla para completarla.</p></section>`;
}
